import type { CategoryNode } from "../types";

/**
 * Tìm node trong cây category theo id, trả về đường dẫn từ gốc tới node đó và chính node (leaf).
 * Trả về null nếu không tìm thấy.
 */
export function findCategoryPathById(
  tree: CategoryNode[],
  targetId: number,
): { path: CategoryNode[]; node: CategoryNode } | null {
  function search(
    nodes: CategoryNode[],
    path: CategoryNode[],
  ): { path: CategoryNode[]; node: CategoryNode } | null {
    for (const node of nodes) {
      const nextPath = [...path, node];
      if (node.id === targetId) {
        return { path: nextPath, node };
      }
      if (node.children?.length) {
        const found = search(node.children, nextPath);
        if (found) return found;
      }
    }
    return null;
  }
  return search(tree, []);
}
